import sympy
import math
from sympy.combinatorics import SymmetricGroup, AlternatingGroup, PermutationGroup, Permutation, DihedralGroup, CyclicGroup

# Top-level setup: named object bindings
S3 = SymmetricGroup(3)
S4 = SymmetricGroup(4)
A4 = AlternatingGroup(4)
D4 = DihedralGroup(4)
C4 = CyclicGroup(4)
V4 = AlternatingGroup(4)
Z2 = CyclicGroup(2)
Z3 = CyclicGroup(3)
Z4 = CyclicGroup(4)
Z6 = CyclicGroup(6)
trivial = CyclicGroup(1)

CONDITION_LABELS = [
    "H_1: S_n is the symmetric group of degree n >= 2",
    "H_2: H is the subgroup of S_n generated by a single transposition",
    "¬Q: S_n is NOT the internal semidirect product of A_n and H"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness):
    h1 = False
    h2 = False
    neg_q = False
    
    try:
        # The conjecture is true for all finite n >= 2.
        # The dropped hypothesis is that n is finite. 
        # For an infinite set, A_n H is the group of all finite permutations, 
        # which is a proper subgroup of the full infinite symmetric group S_n.
        # Thus, S_n is NOT the internal semidirect product of A_n and H for infinite n.
        
        is_inf = False
        if witness == sympy.oo or witness == math.inf:
            is_inf = True
        elif isinstance(witness, str) and ('inf' in witness.lower() or 'oo' in witness.lower()):
            is_inf = True
        elif hasattr(witness, 'is_infinite') and witness.is_infinite:
            is_inf = True
        elif isinstance(witness, tuple) and len(witness) > 0:
            first = witness[0]
            if first == sympy.oo or first == math.inf:
                is_inf = True
            elif isinstance(first, str) and ('inf' in first.lower() or 'oo' in first.lower()):
                is_inf = True
            elif hasattr(first, 'is_infinite') and first.is_infinite:
                is_inf = True
            elif hasattr(first, 'degree'):
                deg = first.degree
                if deg == sympy.oo or deg == math.inf or (hasattr(deg, 'is_infinite') and deg.is_infinite):
                    is_inf = True
                    
        if is_inf:
            return [True, True, True]
            
        # Evaluate finite cases (which should fail to be counterexamples)
        if isinstance(witness, tuple) and len(witness) == 2:
            G_or_n, H = witness
            G = None
            n = None
            
            if isinstance(G_or_n, (int, sympy.Integer)):
                n = int(G_or_n)
                if n >= 2:
                    G = SymmetricGroup(n)
                    h1 = True
            elif hasattr(G_or_n, 'degree') and hasattr(G_or_n, 'order'):
                G = G_or_n
                n = G.degree
                if n >= 2 and G.order() == math.factorial(n):
                    h1 = True
                    
            if h1 and G is not None and hasattr(H, 'is_subgroup'):
                if H.is_subgroup(G) and H.order() == 2:
                    for g in H.generate():
                        if not g.is_Identity:
                            cycles = g.cycles
                            # A single transposition has exactly one cycle of length 2
                            if len(cycles) == 1 and len(cycles[0]) == 2:
                                h2 = True
                            break
                            
            if h1 and h2 and G is not None:
                A = AlternatingGroup(n)
                is_normal = A.is_normal(G)
                int_AH = A.intersect(H)
                is_trivial_int = (int_AH.order() == 1)
                is_product = (A.order() * H.order() == G.order())
                
                is_semidirect = is_normal and is_trivial_int and is_product
                neg_q = not is_semidirect
                
        elif isinstance(witness, (int, sympy.Integer)):
            n = int(witness)
            if n >= 2:
                h1 = True
                h2 = True
                neg_q = False
                
        elif hasattr(witness, 'degree') and hasattr(witness, 'order'):
            n = witness.degree
            if n >= 2 and witness.order() == math.factorial(n):
                h1 = True
                h2 = True
                neg_q = False
                
    except Exception:
        pass
        
    return [h1, h2, neg_q]